const html = $input.first().json.data ?? '';
const base = 'https://empleopublico.jcyl.es';

function absolutizar(href) {
  let url = href.replace(/&amp;/g, '&').trim();
  if (url.startsWith('http')) return url.split('#')[0];
  if (url.startsWith('/')) return `${base}${url.split('#')[0]}`;
  return `${base}/${url.split('#')[0]}`;
}

const convocatorias = new Map();

const regexEnlace =
  /<a[^>]+href="([^"]*Plantilla100Detalle\/\d+\/Convocatoria\/\d+\/Empleo[^"]*)"[^>]*>([\s\S]*?)<\/a>/gi;

let match;
while ((match = regexEnlace.exec(html)) !== null) {
  const url = absolutizar(match[1]);
  const titulo = match[2]
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!convocatorias.has(url)) {
    convocatorias.set(url, titulo || 'Convocatoria JCyL');
  }
}

if (convocatorias.size === 0) {
  throw new Error('No se encontraron enlaces de convocatoria en Empleo público al día.');
}

return [...convocatorias.entries()].map(([url, titulo]) => ({
  json: { url, titulo, origen: 'Empleo público al día' },
}));

function parseKeywords(text) {
  if (!text || String(text).trim() === '') return [];
  return String(text)
    .split(/[,;|\n]+/)
    .map((k) => k.trim().toLowerCase())
    .filter((k) => k.length >= 2);
}

function normalize(str) {
  return String(str)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function matchesKeyword(titulo, keywords) {
  const hay = normalize(titulo);
  for (const kw of keywords) {
    if (hay.includes(normalize(kw))) return kw;
  }
  return null;
}

const enlaces = $('Extraer enlaces JCyL').all().map((i) => i.json);
const filas = $input.all().map((i) => i.json);

const urlsConocidas = new Set(
  filas.map((f) => String(f.URL ?? '').trim()).filter(Boolean),
);

const filaFiltro = filas.find(
  (f) =>
    String(f.Nombre ?? '').trim().toLowerCase() === '_descubrimiento' &&
    !String(f.URL ?? '').trim(),
);

let keywords = [];
if (filaFiltro?.Palabras_clave) {
  keywords = parseKeywords(filaFiltro.Palabras_clave);
} else {
  const set = new Set();
  for (const f of filas) {
    for (const k of parseKeywords(f.Palabras_clave)) set.add(k);
  }
  keywords = [...set];
}

const filtrarPorKeywords = keywords.length > 0;
const nuevas = [];

for (const item of enlaces) {
  if (urlsConocidas.has(item.url)) continue;

  if (filtrarPorKeywords) {
    const match = matchesKeyword(item.titulo, keywords);
    if (!match) continue;
    nuevas.push({ ...item, palabraCoincidente: match });
  } else {
    nuevas.push({ ...item, palabraCoincidente: null });
  }
}

if (nuevas.length === 0) {
  return [
    {
      json: {
        hayNuevas: false,
        totalEncontradas: enlaces.length,
        totalNuevas: 0,
        filtrarPorKeywords,
        keywordsActivas: keywords.join(', '),
        ahora: new Date().toLocaleString('es-ES'),
      },
    },
  ];
}

return nuevas.map((item) => ({
  json: {
    hayNuevas: true,
    url: item.url,
    titulo: item.titulo,
    origen: item.origen,
    palabraCoincidente: item.palabraCoincidente,
    keywordsActivas: keywords.join(', '),
    ahora: new Date().toLocaleString('es-ES'),
  },
}));

